import{n as e,o as t,r as n}from"./app-C9M3NSvs.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/program/tools/ip_proxy.html","title":"IP 代理","lang":"zh-CN","frontmatter":{"description":"IP 代理 IP 代理（IP Proxy）是一种网络服务，允许用户通过一个中间服务器（代理服务器）访问互联网。简单来说，它就是通过改变用户的 IP 地址来实现匿名上网、绕过地域限制、提高网络安全性等功能。 工作原理 请求转发：用户的请求首先会发送到代理服务器，而不是直接发送到目标网站。 IP 替换：代理服务器将用户的请求转发给目标网站时，使用的是代理服...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"IP 代理\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/program/tools/ip_proxy.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"IP 代理"}],["meta",{"property":"og:description","content":"IP 代理 IP 代理（IP Proxy）是一种网络服务，允许用户通过一个中间服务器（代理服务器）访问互联网。简单来说，它就是通过改变用户的 IP 地址来实现匿名上网、绕过地域限制、提高网络安全性等功能。 工作原理 请求转发：用户的请求首先会发送到代理服务器，而不是直接发送到目标网站。 IP 替换：代理服务器将用户的请求转发给目标网站时，使用的是代理服..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1746697389000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":1.33,"words":399},"filePathRelative":"program/tools/ip_proxy.md","autoDesc":true}`),a={name:`ip_proxy.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h1 id="ip-代理" tabindex="-1"><a class="header-anchor" href="#ip-代理"><span>IP 代理</span></a></h1><p>IP 代理（IP Proxy）是一种网络服务，允许用户通过一个中间服务器（代理服务器）访问互联网。简单来说，它就是通过改变用户的 IP 地址来实现匿名上网、绕过地域限制、提高网络安全性等功能。</p><h2 id="工作原理" tabindex="-1"><a class="header-anchor" href="#工作原理"><span>工作原理</span></a></h2><ol><li><strong>请求转发</strong>：用户的请求首先会发送到代理服务器，而不是直接发送到目标网站。</li><li><strong>IP 替换</strong>：代理服务器将用户的请求转发给目标网站时，使用的是代理服务器的 IP 地址，而不是用户的真实 IP 地址。</li><li><strong>返回响应</strong>：目标网站的响应返回给代理服务器，代理服务器再将响应转发给用户。</li></ol><h2 id="常见-ip-代理类型" tabindex="-1"><a class="header-anchor" href="#常见-ip-代理类型"><span>常见 IP 代理类型</span></a></h2><ul><li><strong>匿名代理</strong>：隐藏用户的真实 IP 地址，且目标网站无法知道用户是否使用了代理。</li><li><strong>透明代理</strong>：不隐藏用户的真实 IP 地址，目标网站可以知道用户使用了代理。</li><li><strong>高匿代理（高级匿名代理）</strong>：彻底隐藏用户的真实 IP 地址，并且不透露用户正在使用代理。</li></ul><h2 id="应用场景" tabindex="-1"><a class="header-anchor" href="#应用场景"><span>应用场景</span></a></h2><ul><li><strong>突破地域限制</strong>：例如，访问仅限特定地区的内容或服务（如 Netflix、YouTube 等）。</li><li><strong>匿名浏览</strong>：保护用户隐私，避免暴露真实 IP 地址。</li><li><strong>爬虫和数据抓取</strong>：大量的网络爬虫和数据抓取程序使用代理来避免被封 IP。</li><li><strong>安全性</strong>：防止通过 IP 追踪到用户的身份或位置。</li></ul>`,8)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};